private void enlarge(final int size) {
    // Calculate the new capacity of the byte vector
    int newCapacity = this.capacity + size;

    // Create a new byte array with the new capacity
    byte[] newData = new byte[newCapacity];

    // Copy the existing data from this.data to the new byte array
    System.arraycopy(this.data, 0, newData, 0, this.data.length);

    // Set the new data array and capacity
    this.data = newData;
    this.capacity = newCapacity;
}

