        return null;
    }

    StringBuilder builder = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            builder.append(unescapeJavaChar(str, i));
            i++;
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

private static char unescapeJavaChar(String str, int i) throws Exception {
    char c = str.charAt(i);
    switch (c) {
        case 'n':
            return '\n';
        case 'r':
            return '\r';
        case 't':
            return '\t';
        case 'b':
            return '\b';
        case 'f':
            return '\f';
        case '\'':
            return '\'';
        case '\"':
            return '\"';
        case '\\':
            return '\\';
        default:
            throw new Exception("Invalid escape sequence: \\" + c);
    }
}
