private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices form a complete subgraph
    Set<V> completeSubgraphVertices = new HashSet<>(vertices);
    for (V vertex : vertices) {
        for (V neighbor : graph.neighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }
    // Check if the complete subgraph is a clique
    for (V vertex1 : completeSubgraphVertices) {
        for (V vertex2 : completeSubgraphVertices) {
            if (vertex1 != vertex2 && !graph.hasEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}
