private void pop(final String descriptor) {
    if (descriptor.startsWith("(")) {
        // Method descriptor
        final String[] argTypes = descriptor.substring(1, descriptor.length() - 1).split(";");
        for (int i = 0; i < argTypes.length; i++) {
            pop(argTypes[i]);
        }
    } else {
        // Type descriptor
        final String type = descriptor.substring(1);
        if (type.equals("I")) {
            // Integer
            popInt();
        } else if (type.equals("F")) {
            // Float
            popFloat();
        } else if (type.equals("D")) {
            // Double
            popDouble();
        } else if (type.equals("J")) {
            // Long
            popLong();
        } else if (type.equals("Z")) {
            // Boolean
            popBoolean();
        } else if (type.equals("B")) {
            // Byte
            popByte();
        } else if (type.equals("C")) {
            // Char
            popChar();
        } else if (type.equals("S")) {
            // Short
            popShort();
        } else {
            throw new IllegalArgumentException("Unsupported type descriptor: " + descriptor);
        }
    }
}

