public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] columns = line.split(",");
            if (columns.length == 3) {
                long timestamp = Long.parseLong(columns[0]);
                String threadName = columns[1];
                String threadState = columns[2];
                ProfileAnalyzeTimeRange timeRange = timeRanges.stream()
                        .filter(tr -> tr.getStartTime() <= timestamp && tr.getEndTime() >= timestamp)
                        .findFirst()
                        .orElse(null);
                if (timeRange != null) {
                    ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, threadState, timestamp);
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }
    }
    return threadSnapshots;
}
